# -*- coding: utf-8 -*-
# The Tea-Horse Road: names and stories, by node (zh, en). Fog, gu poison and the mountain god; the Thousand Li's
# mule train, its guard captain and the sealed box it carried.
TEA = {
 'name': ('茶马古道', 'The Tea-Horse Road'),
 'start': ('雅州茶关', 'Tea Gate of Yazhou',
  """茶关的税吏验完货，在通关文书背面盖了两个印。你问为什么是两个，他说：「一个给你们，一个给十年前没盖完的那支马帮。」他把一块发霉的茶砖塞进你手里，砖上压着「千里号」三个字。「他们走的时候说，茶砖吃完就回来。」""",
  """The tax clerk checks your goods and stamps the back of your pass twice. Why twice, you ask. "One for you," he says, "and one for the mule train I never finished stamping, ten years ago." He presses a mouldy brick of tea into your hand, Thousand Li pressed into it. "They said they would be back when the tea ran out."""),
 1: {
  'title': ('雾驿', 'The Fog Posts'),
  'n1': ('茶垭口', 'Tea Pass', 'enemy',
   """垭口上的山匪不劫茶，专劫马。被劫走的马第二天自己回来，鞍子上挂着一串铜铃，铃舌全被拔掉了。""",
   """The brigands at the pass take no tea, only horses. The horses come back on their own the next day, a string of bells on each saddle, every clapper pulled out."""),
  'n2': ('雾中驿', 'The Post in the Fog', 'story',
   """雾浓得看不见自己的手。驿站里有人在点名，一个名字一个名字念过去，念到的人就应一声「到」。你们谁也没出声，可点名簿上，你们的名字后面都画了勾。""",
   """The fog is so thick you cannot see your own hands. Someone in the post is calling the roll, name by name, and each name answers "Here." None of you said a word, yet in the roll book every one of your names has been ticked."""),
  'n3': ('背夫寨', 'Porters\' Stockade', 'enemy2',
   """背夫们背着比人还高的茶包，一天走六十里山路。寨主说他们欠了马帮的债，要拿开拓队的命来还。背夫们放下茶包，从里面抽出了刀。""",
   """The porters carry bales of tea taller than themselves, sixty li of mountain a day. Their chief says they owe the mule train a debt, and your lives will pay it. The porters set down their bales and draw knives out of them."""),
  'n4': ('锅庄', 'The Hearth House', 'supply',
   """锅庄里的火塘十年没熄过，被一伙兵痞占着，过路人要烤火得交一包茶。赶走他们以后，掌柜的从火塘灰里扒出一只铁盒，里面是一张没写完的收据：「收千里号茶四十驮，欠——」。""",
   """The fire in the hearth house has not gone out in ten years. A gang of deserters holds it, and travellers pay a bale of tea to sit by it. When they are gone, the keeper rakes an iron box out of the ashes: an unfinished receipt. "Received of the Thousand Li, forty loads of tea. Owing—\""""),
  'n5': ('茶马互市', 'Tea-for-Horses Market', 'key',
   """番人牵着马来换茶，一匹马换几驮茶，几百年都是一个价。你们重新立起了官秤，番人的头人摸了摸秤杆上的刻痕，说：「这杆秤，我认得。」""",
   """Highlanders lead their horses down to trade for tea, so many loads for a horse, the same price for centuries. You set the official scales up again. The headman runs a finger along the notches on the beam. "I know this scale," he says."""),
  'n6': ('马帮客栈', 'Muleteers\' Inn', 'merchant',
   """客栈老板是个哑巴，用算盘跟人讲价。他卖的东西里有一样很怪：一串没有铃舌的铜铃，标价比别的都高。""",
   """The innkeeper is mute and bargains with an abacus. Among his goods is one odd thing: a string of bells without clappers, priced above everything else."""),
  'n7': ('瘴林', 'The Miasma Woods', 'enemy',
   """林子里的瘴气是绿色的，吸一口就头昏眼花。土兵们戴着湿布从雾里冲出来，你分不清他们是人，还是瘴气凝成的影子。""",
   """The miasma in the woods is green; one breath and your head swims. Native troops with wet cloths over their faces charge out of it, and you cannot tell whether they are men or shadows the fog has thickened into."""),
  'n8': ('留字崖', 'Cliff of Messages', 'story',
   """崖壁上刻满了过路人留的字，大多是「某某到此」。最高处有一行字，刻得很深：「陆九护匣至此，匣在人在」。字的下面，有人后来补了一句，墨还没干：「人不在了。」""",
   """The cliff is covered in what travellers have cut into it, mostly "So-and-so was here." Highest of all, cut deep: "Lu Jiu guarded the box this far. While I live, so does the box." Beneath it someone has since added, the ink still wet: "He does not live.\""""),
  'b': ('雾驿主', 'Master of the Fog Posts', 'boss',
   """雾驿主住在最后一座驿站里，从不露面。他的声音从四面八方传来：「十年前我替他们点过名，三百人，一个不少。可走出雾的时候，只剩下二百九十九。」雾里亮起一圈火把，土兵从三面围了上来。「少的那一个，是不是你？」""",
   """The Master of the Fog Posts lives in the last post and never shows himself. His voice comes from every side. "Ten years ago I called their roll: three hundred, not one missing. When they came out of the fog there were two hundred and ninety-nine." A ring of torches flares up in the fog; native troops close in from three sides. "Was the missing one you?\""""),
 },
 2: {
  'title': ('蛊寨', 'The Gu Villages'),
  'n1': ('竹桥', 'The Bamboo Bridge', 'enemy',
   """竹桥只容一人通过，桥那头的寨兵吹着芦笙。笙声一停，桥下的河里就浮起一排竹筏，筏上站满了人。""",
   """The bamboo bridge takes one man at a time. On the far side the village guards play reed pipes; when the piping stops, a line of bamboo rafts rises from the river below, crowded with men."""),
  'n2': ('蛊婆', 'The Gu Woman', 'story',
   """蛊婆给每个人倒了一碗酒，说喝了就不会在寨子里迷路。你们没喝。夜里，有人听见自己的碗在桌上转圈，转了一整夜，碗底刻着一个「千」字。""",
   """The gu woman pours each of you a bowl of wine: drink, she says, and you will not lose your way in the village. You do not drink. In the night someone hears his bowl turning on the table, round and round all night. Cut into its foot: the character for thousand."""),
  'n3': ('吊脚楼', 'Stilt Houses', 'enemy2',
   """吊脚楼一层叠一层，弩手就藏在楼板下面。他们射的箭不带箭头，只带一根细线，线的另一头不知道拴在哪里。""",
   """Stilt house rises over stilt house, and crossbowmen lie under the floorboards. Their bolts have no heads, only a thin thread, its other end tied who knows where."""),
  'n4': ('药田', 'The Herb Terraces', 'supply',
   """药田里种的都是解毒的草，被一伙寨丁圈了起来，要拿人来换。你们打散了寨丁，药农们送来了草药和干粮，说这些草是十年前一个汉人教他们种的，他说「后面还有人要来」。""",
   """The terraces grow nothing but antidotes, and a band of village men has fenced them off: a person for a basket. Once you scatter them, the growers bring herbs and dry rations. A man from the lowlands taught them to grow these ten years ago, they say. "More are coming after me," he told them."""),
  'n5': ('寨老会', 'Council of Elders', 'key',
   """寨老们围着火塘坐成一圈，听你们讲来意。最老的那个从怀里掏出半块茶砖，和你在雅州收到的那块一对，正好是一整块。「茶来了，」他说，「这条路就可以通了。」""",
   """The elders sit round the hearth and hear you out. The oldest takes half a brick of tea from his coat; set against the one you were given at Yazhou, the two halves make one whole. "The tea has come," he says. "The road may open.\""""),
  'n6': ('银匠铺', 'The Silversmith', 'merchant',
   """银匠打的银饰能防蛊，戴上以后，蛊虫就不敢近身。他也卖别的东西，从中原来的、从雪山来的、从海那边来的，他说都是马帮当年留下的。""",
   """The silversmith's ornaments ward off gu: wear one and the worms keep away. He sells other things too, from the plains, from the snow mountains, from over the sea. All left by the mule train, he says."""),
  'n7': ('蛊林', 'The Gu Forest', 'enemy',
   """林子里每一棵树上都挂着陶罐，罐口封着红布。守林人揭开一只罐子，里面爬出来的不是虫，是一缕一缕的雾。雾散开，就成了人。""",
   """A clay jar hangs from every tree in the forest, its mouth sealed with red cloth. The forest keeper opens one. What crawls out is no worm but threads of fog, and where the fog spreads, there are men."""),
  'n8': ('同心蛊', 'The Bound-Heart Gu', 'story',
   """蛊婆告诉你们，十年前马帮里有三百人，一起喝了同心蛊。同心蛊不害人，只是从此三百人同生同死，谁也不能先走一步。「所以他们一直在等，」她说，「等最后一个人走到。」""",
   """Ten years ago, the gu woman tells you, three hundred men of the mule train drank the bound-heart gu together. It harms no one. Only, from then on, the three hundred live and die together, and none may go on ahead. "So they wait," she says. "For the last of them to arrive.\""""),
  'b': ('蛊王', 'The Gu King', 'boss',
   """蛊王坐在一口大缸边，缸里养着一只三寸长的金蚕。「三百个人的心都拴在它身上，」他说，「它饿了十年了。」他敲了敲缸沿，寨子里的芦笙一齐响了起来，寨兵从四面的吊脚楼里涌了出来。""",
   """The Gu King sits beside a great vat. In it lives a golden silkworm three inches long. "Three hundred hearts are tied to it," he says. "It has gone hungry ten years." He taps the rim of the vat; the reed pipes of the whole village sound at once, and warriors pour from every stilt house."""),
 },
 3: {
  'title': ('悬崖栈道', 'The Cliff Galleries'),
  'n1': ('溜索', 'The Rope Slide', 'enemy',
   """江面上只有一根溜索。对岸的人等你们滑到一半，才开始砍绳子。""",
   """A single rope slide crosses the river. The men on the far bank wait until you are halfway over before they start hacking at the rope."""),
  'n2': ('铃声', 'Bells in the Gorge', 'story',
   """峡谷里传来马铃声，可那些铃是没有铃舌的。声音从崖壁这头弹到那头，一路往上走，走到云里就没了。你们数了，一共二百九十九声。""",
   """Mule bells sound in the gorge, bells without clappers. The sound bounces from wall to wall, climbing, until it is lost in the clouds. You count: two hundred and ninety-nine."""),
  'n3': ('栈道关', 'Gallery Gate', 'enemy2',
   """栈道修在绝壁上，木桩一半已经朽了。关卡上的守兵穿着十年前马帮的号衣，号衣上的字已经褪得看不清了。""",
   """The gallery hangs on a sheer wall, half its beams rotten. The guards at the gate wear the mule train's livery of ten years ago, its lettering faded past reading."""),
  'n4': ('岩洞营', 'Cave Camp', 'supply',
   """岩洞里堆着成捆的干草和成袋的青稞，被一伙流兵占了。打跑流兵以后，你们发现洞壁上用炭画着一个记号：一个箱子，箱子上画着一把锁，锁上画着一只眼睛。""",
   """The cave is stacked with hay and sacks of highland barley, and a band of stragglers holds it. Once they flee, you find a mark drawn in charcoal on the wall: a box, a lock on the box, an eye on the lock."""),
  'n5': ('雪线驿', 'Post at the Snow Line', 'key',
   """雪线上的驿站是马帮最后一个歇脚的地方。驿丞翻出一本十年前的货单，最后一页写着：「茶尽，马尽，匣未尽。」你们把驿站重新开了张，雪山那边的人第二天就赶着牦牛来了。""",
   """The post at the snow line was the mule train's last halt. The postmaster digs out a bill of goods from ten years ago. The last page reads: "Tea gone, horses gone, the box not yet." You open the post for business again; next day herders come down from the snows with their yaks."""),
  'n6': ('喇嘛商队', 'The Lama\'s Caravan', 'merchant',
   """一队喇嘛赶着牦牛往山下走，驮着酥油、氆氇和一些说不出来历的东西。领头的喇嘛说，雪山上的神庙已经十年没开过门了。""",
   """A line of lamas drives yaks down the mountain, laden with butter, wool cloth and things of no clear origin. The temple on the snow mountain, says the lama at their head, has not opened its doors in ten years."""),
  'n7': ('鹰嘴岩', 'Eagle-Beak Rock', 'enemy',
   """鹰嘴岩上的守兵往下推石头，推完一轮，就有人在岩顶上喊：「陆镖头说了，谁也不许上山。」""",
   """The guards on Eagle-Beak Rock roll boulders down; after each volley someone shouts from the top, "Captain Lu says no one goes up the mountain.\""""),
  'n8': ('镖头的信', 'The Captain\'s Letter', 'story',
   """岩缝里塞着一封信，油布包了好几层。写信的人叫陆九，是千里号马帮的镖头：「匣中之物，须面呈来人。来人若是朝廷的，就开匣；若不是，就让他回去。」信封上写着收信人：后来者。""",
   """A letter is wedged in a crack in the rock, wrapped in oilcloth many times. The writer is Lu Jiu, captain of the Thousand Li's guard. "What is in the box must be shown to whoever comes. If they come from the court, open it; if not, send them home." On the cover, the addressee: Whoever Comes After."""),
  'b': ('镖头陆九', 'Lu Jiu, Captain of the Guard', 'boss',
   """栈道的尽头站着一个人，身上落满了雪，像是站了很多年。他背上的铁匣上了三道锁。「我答应过的，」陆九说，「匣在人在。你们要拿走它，得先让我知道，你们比我更护得住它。」他身后的镖师们一齐拔刀，刀上都结着冰。""",
   """At the end of the gallery a man stands deep in snow, as if he has stood there for years. The iron box on his back is fastened with three locks. "I gave my word," says Lu Jiu. "While I live, so does the box. To take it, first show me you can guard it better than I." The guards behind him draw together, their blades crusted with ice."""),
 },
 4: {
  'title': ('雪山神庙', 'The Temple on the Snow Mountain'),
  'n1': ('转山路', 'The Pilgrims\' Circuit', 'enemy',
   """转山的人一步一叩首，绕着雪山走。守山的武僧拦在路上，说没有转满三圈的人不能上山。你们没有时间转三圈。""",
   """Pilgrims circle the snow mountain, prostrating at every step. Warrior monks bar the road: no one goes up who has not gone round three times. You do not have time for three times."""),
  'n2': ('玛尼堆', 'The Mani Cairn', 'story',
   """路边的玛尼堆上，每块石头都刻着经文。有一块刻的不是经文，是一本账：「千里号，茶四十驮，马六十匹，人三百。匣一。」账的最后，有人用指甲划了一道，像是一笔一笔地在数日子。""",
   """Every stone in the roadside cairn is carved with scripture, all but one. That one is carved with an account: "Thousand Li: tea, forty loads; horses, sixty; men, three hundred. Box, one." Beneath it someone has scratched with a fingernail, stroke after stroke, as if counting days."""),
  'n3': ('雪崩谷', 'Avalanche Valley', 'enemy2',
   """谷两边的雪坡上埋伏着人。他们不放箭，只是一齐大喊。喊声一起，雪就塌了下来，雪里裹着刀。""",
   """Men lie in wait on the snow slopes either side of the valley. They loose no arrows; they shout, all together. At the shout the snow comes down, and there are blades in it."""),
  'n4': ('温泉寺', 'Hot Spring Monastery', 'supply',
   """温泉边的小寺被一伙盗马贼占着。赶走他们以后，寺里的老喇嘛给你们煮了酥油茶。茶是千里号的茶，他说十年来一直省着喝，现在可以不用省了。""",
   """Horse thieves hold the little monastery by the hot springs. When they are gone, the old lama brews you butter tea. It is the Thousand Li's tea, he says; he has rationed it ten years, and now he need not."""),
  'n5': ('神庙集市', 'The Temple Fair', 'key',
   """一年一度的庙会，雪山上下的人都来了。你们在集上摆开朝廷的货，头一天就卖空了。神庙的执事把一枚铜印交给你们：「从此以后，山上山下的买卖，都认这枚印。」""",
   """Once a year the temple holds its fair, and everyone from above and below the snows comes. You lay out the court's goods; they are gone the first day. The temple steward hands you a bronze seal. "From now on, all trade up and down the mountain goes by this seal.\""""),
  'n6': ('天葬台下', 'Below the Sky Burial Ground', 'merchant',
   """天葬台下住着一个商人，卖的都是别人用不着了的东西。他说，雪山上的人走的时候，什么都不带。他这里有一样东西一天只卖一颗，是一种丹药，说是留给「要从头再来的人」的。""",
   """A merchant lives below the sky burial ground and sells what others no longer need. Those who die on the mountain take nothing with them, he says. One thing he sells only one a day: a pill, for "someone who must begin again.\""""),
  'n7': ('神庙护法', 'Guardians of the Temple', 'enemy',
   """神庙门前的护法戴着牛头面具，手持金刚杵。他们的面具下面没有脸，只有一团雾，和茶垭口的雾一模一样。""",
   """The guardians at the temple doors wear yak-headed masks and carry vajra clubs. Beneath the masks there are no faces, only fog, the very fog of Tea Pass."""),
  'n8': ('开匣', 'The Box Opened', 'story',
   """铁匣打开了。里面没有金银，只有半张海图，海图的边上写着一行小字：「陆路已尽，余下的，走海路。」海图背面盖着朝廷的印，和雅州茶关那两个印，一模一样。""",
   """The iron box opens. There is no gold or silver in it, only half a sea chart, and along its edge in small characters: "The land roads end here. The rest goes by sea." On the back of the chart is the court's seal, the very seal stamped twice at the Tea Gate of Yazhou."""),
  'b': ('山神', 'The Mountain God', 'boss',
   """神庙的大殿里供着山神，山神的脸是陆九的脸。「我答应过他们，」山神说，「护住这条路，等后来的人。」殿外风雪大作，山神的护法从三面围了上来。「现在你们来了。让我看看，你们配不配接着走下去。」""",
   """In the great hall of the temple sits the mountain god, and the mountain god has Lu Jiu's face. "I promised them," it says, "to keep this road and wait for whoever came after." Outside a blizzard rises; the god's guardians close in from three sides. "Now you have come. Let me see whether you are fit to go on.\""""),
 },
}
